#!/usr/bin/env bash
# Patches a vendored checkout of FalkorDB/benchmark's ui/ app so its static
# export is relocatable under an arbitrary GitHub Pages sub-path.
#
# GitHub Pages project sites are always served under /<repo>/, never domain
# root, and this repo further nests each benchmark view under
# /benchmark/... (canonical, main/edge trend) or /benchmark/branch/<slug>/
# (per-branch preview). Next's `basePath` config option already rewrites its
# own <Link>/<Image>/asset URLs automatically, but it does NOT rewrite plain
# fetch() calls to hardcoded absolute strings — and the falkordb-compare
# dashboard has a few of those (the initial dataUrl, and the "browse past
# runs" history switcher). This script fixes those specific call sites to
# read the same base path via a NEXT_PUBLIC_ env var, which Next's build
# *does* inline into client bundles.
#
# Validated against FalkorDB/benchmark commit
# deca7752cbd8cdeb333493569472ede385d5b5db (release v2.2) — the five require()
# patterns below still match its ui/ source. The grep -qF guards below make
# any future upstream refactor of these exact lines fail loudly here instead
# of silently shipping a broken sub-path deployment — if that happens, this
# script needs a one-time update to match the new source.
#
# This script is almost entirely literal JavaScript/TypeScript patched in via
# sed; the single-quoted `${...}` fragments are JS template placeholders that
# must NOT be shell-expanded, so SC2016 is a false positive throughout.
# shellcheck disable=SC2016
set -euo pipefail

: "${UI_DIR:?UI_DIR (path to the vendored FalkorDB/benchmark ui/ directory) is required}"
: "${BASE_PATH:?BASE_PATH is required (e.g. /falkordb-rs-next-gen/benchmark)}"

PAGE="$UI_DIR/app/falkordb-compare/page.tsx"
DASHBOARD="$UI_DIR/app/components/dashboard.tsx"

require() {
  local file="$1" pattern="$2"
  grep -qF "$pattern" "$file" || {
    echo "::error::expected pattern not found in $file — upstream FalkorDB/benchmark ui/ changed; update .github/scripts/benchmark/patch-ui.sh to match. pattern=$pattern" >&2
    exit 1
  }
}

require "$PAGE" 'const dataUrl = "/summaries/falkordb_vs_falkordb.json";'
require "$PAGE" '"falkordb-c", "falkordb-rs",'
require "$DASHBOARD" 'const response = await fetch("/summaries/manifest.json");'
require "$DASHBOARD" 'setActiveUrl(`/summaries/${val}`);'
require "$DASHBOARD" 'activeUrl.replace("/summaries/", "")'

# 1. Seed dataUrl (and therefore the initial server-side read + the
#    dropdown's "current run" option) with the base path.
sed -i.bak \
  's#const dataUrl = "/summaries/falkordb_vs_falkordb.json";#const dataUrl = `${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/summaries/falkordb_vs_falkordb.json`;#' \
  "$PAGE"

# 1b. The falkordb-compare page's vendor allow-list hardcodes falkordb-c +
#     falkordb-rs but not our PR variant (falkordb-pr), so filterDataByVendors
#     would drop the PR and the detailed dashboard would show only the C engine
#     vs published Rust. Add falkordb-pr after every falkordb-rs (covers both
#     comparisonVendors and the initial Vendors selection). Harmless for
#     canonical A/B runs where falkordb-pr simply isn't in the data.
sed -i.bak 's#"falkordb-rs",#"falkordb-rs", "falkordb-pr",#g' "$PAGE"

# 2. Manifest fallback fetch, 3. history-switcher fetch, 4. the filename
#    extraction that feeds the <select> — all need the same base-path
#    awareness (split() instead of replace() so it works whether or not a
#    prefix is present).
sed -i.bak \
  -e 's#const response = await fetch("/summaries/manifest.json");#const response = await fetch(`${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/summaries/manifest.json`);#' \
  -e 's#setActiveUrl(`/summaries/\${val}`);#setActiveUrl(`${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/summaries/${val}`);#' \
  -e 's#activeUrl\.replace("/summaries/", "")#activeUrl.split("/summaries/").pop()#' \
  "$DASHBOARD"

rm -f "$PAGE.bak" "$DASHBOARD.bak"

cat > "$UI_DIR/next.config.ts" << EOF
import type { NextConfig } from "next";

// Generated by .github/scripts/benchmark/patch-ui.sh — do not edit by hand.
const BASE_PATH = "${BASE_PATH}";

const nextConfig: NextConfig = {
  output: "export",
  images: { unoptimized: true },
  // Directory-style output (falkordb-compare/index.html) so GitHub Pages
  // serves clean /falkordb-compare/ URLs instead of requiring a literal
  // .html extension.
  trailingSlash: true,
  basePath: BASE_PATH,
  env: { NEXT_PUBLIC_BASE_PATH: BASE_PATH },
};

export default nextConfig;
EOF

echo "Patched $UI_DIR for static export under $BASE_PATH"
